sys_script_email.script:
(function runMailScript(/* GlideRecord */ current,
          /* TemplatePrinter */ template,
          /* Optional EmailOutbound */ email,
          /* Optional GlideRecord */ email_action,
          /* Optional GlideRecord */ event) {

    // Instance URL
    var instanceURL = gs.getProperty('glide.servlet.uri');

    // RITM URL
    var ritmURL = instanceURL + current.getLink(true);

    template.print("<p>Hello Team,</p>");

    template.print("<p>A Jira story has been created for the following ServiceNow request.</p>");

    template.print("<table border='1' cellpadding='6' cellspacing='0' style='border-collapse:collapse;'>");

    template.print("<tr>");
    template.print("<td><b>RITM</b></td>");
    template.print("<td><a href='" + ritmURL + "'>" + current.number + "</a></td>");
    template.print("</tr>");

    template.print("<tr>");
    template.print("<td><b>Short Description</b></td>");
    template.print("<td>" + current.short_description + "</td>");
    template.print("</tr>");

    template.print("<tr>");
    template.print("<td><b>Requested For</b></td>");
    template.print("<td>" + current.request.requested_for.getDisplayValue() + "</td>");
    template.print("</tr>");

    template.print("<tr>");
    template.print("<td><b>Jira Story ID</b></td>");
    template.print("<td>" + event.parm2 + "</td>");
    template.print("</tr>");

    template.print("</table>");

    template.print("<br/>");

    template.print("<p>Please use the Jira Story ID for tracking and follow-up activities related to this request.</p>");

    template.print("<p>Thank you.</p>");

})(current, template, email, email_action, event);
